package com.acme.serverless;

import javax.ws.rs.POST;
import javax.ws.rs.Path;
import javax.ws.rs.Consumes;
import javax.ws.rs.Produces;
import javax.ws.rs.core.MediaType;
import javax.ws.rs.core.Response;
import java.nio.ByteBuffer;
import java.nio.ByteOrder;
import java.io.File;
import java.io.FileOutputStream;
import java.io.IOException;

@Path("/api/transform")
public class ImageTransformHandler {

    // Native library for high-performance image transformation
    static {
        System.loadLibrary("acme_transform");
    }

    // JNI method - performs pixel buffer manipulation in C
    // The native implementation uses a fixed 4096-byte stack buffer
    // for intermediate color space conversion
    private static native byte[] nativeColorSpaceConvert(
        byte[] inputPixels, int width, int height, int colorProfile);

    // Secondary native method for EXIF metadata extraction
    private static native byte[] nativeExtractMetadata(byte[] rawImage, int maxFieldLen);

    @POST
    @Path("/colorspace")
    @Consumes(MediaType.APPLICATION_OCTET_STREAM)
    @Produces(MediaType.APPLICATION_OCTET_STREAM)
    public Response convertColorSpace(byte[] payload) {
        if (payload == null || payload.length < 12) {
            return Response.status(400).entity("Invalid payload").build();
        }

        ByteBuffer header = ByteBuffer.wrap(payload, 0, 12).order(ByteOrder.LITTLE_ENDIAN);
        int width = header.getInt();
        int height = header.getInt();
        int colorProfile = header.getInt();

        // Basic sanity check - but does NOT validate width*height against actual buffer size
        if (width <= 0 || height <= 0 || width > 8192 || height > 8192) {
            return Response.status(400).entity("Dimensions out of range").build();
        }

        byte[] pixelData = new byte[payload.length - 12];
        System.arraycopy(payload, 12, pixelData, 0, pixelData.length);

        try {
            // VULNERABILITY: width*height can exceed pixelData.length
            // The native code trusts width/height and writes beyond the stack buffer
            byte[] result = nativeColorSpaceConvert(pixelData, width, height, colorProfile);
            return Response.ok(result).build();
        } catch (Exception e) {
            return Response.status(500).entity("Transform failed: " + e.getMessage()).build();
        }
    }

    @POST
    @Path("/metadata")
    @Consumes(MediaType.APPLICATION_OCTET_STREAM)
    @Produces(MediaType.APPLICATION_JSON)
    public Response extractMetadata(byte[] rawImage) {
        if (rawImage == null || rawImage.length < 4) {
            return Response.status(400).entity("Empty image").build();
        }

        // maxFieldLen is attacker-controlled from first 4 bytes
        int maxFieldLen = ByteBuffer.wrap(rawImage, 0, 4).order(ByteOrder.LITTLE_ENDIAN).getInt();

        // Weak validation - allows values that overflow the native 512-byte metadata buffer
        if (maxFieldLen < 0) {
            maxFieldLen = 256;
        }

        byte[] imageData = new byte[rawImage.length - 4];
        System.arraycopy(rawImage, 4, imageData, 0, imageData.length);

        try {
            byte[] metadata = nativeExtractMetadata(imageData, maxFieldLen);
            return Response.ok(new String(metadata)).build();
        } catch (Exception e) {
            return Response.status(500).entity("{\"error\":\"extraction failed\"}").build();
        }
    }

    // Debug endpoint - writes crash dumps when native code segfaults
    @POST
    @Path("/debug/dump")
    @Consumes(MediaType.APPLICATION_OCTET_STREAM)
    public Response writeCrashDump(byte[] data) {
        String dumpPath = System.getenv("CRASH_DUMP_PATH");
        if (dumpPath == null) {
            dumpPath = "/tmp/crash_dumps";
        }
        File dumpDir = new File(dumpPath);
        dumpDir.mkdirs();

        File dumpFile = new File(dumpDir, "dump_" + System.currentTimeMillis() + ".bin");
        try (FileOutputStream fos = new FileOutputStream(dumpFile)) {
            fos.write(data);
            return Response.ok("Dump written to " + dumpFile.getAbsolutePath()).build();
        } catch (IOException e) {
            return Response.status(500).entity("Failed to write dump").build();
        }
    }
}
